'use strict';
var assert=require('assert'),fs=require('fs'),path=require('path');
var io=require('./stop-io'),denied=require('./denied-io'),missing=require('./missing-io');
var root=process.argv[2],journal=root+'/private/journal',raw=' { "v":1, "seq":0, "prev":null, "phase":"blocked", "seen":[], "consumed":[], "intents":[] }\n';
var tests=[],count=0,adapters=[];
function test(name,fn){tests.push([name,fn]);}
function adapter(){var a=io.create();adapters.push(a);return a;}
function reject(p){return p.then(function(){throw Error('expected rejection');},function(e){return e;});}
function reset(){fs.readdirSync(journal).forEach(function(n){fs.unlinkSync(journal+'/'+n);});fs.writeFileSync(journal+'/entry.0000.json',raw,{mode:384});}
function check(v){assert.strictEqual(v.status,'snapshot');assert.strictEqual(v.records.length,1);assert.strictEqual(v.records[0].name,'entry.0000.json');assert.strictEqual(v.records[0].raw,raw);}
function closeAll(){var list=adapters;adapters=[];return Promise.all(list.map(function(a){return a.close();}));}

test('default missing executable denies',function(){var entered=false;return reject(missing.withControllerTransaction(function(){entered=true;throw Error('must not enter');})).then(function(){assert.strictEqual(entered,false);return missing.close();});});
test('production missing binding denies',function(){var entered=false;return reject(denied.withControllerTransaction(function(){entered=true;throw Error('must not enter');})).then(function(){assert.strictEqual(entered,false);return denied.close();});});
test('actual child reads exact raw and rejects stale tx',function(){var a=adapter(),old;return a.withControllerTransaction(function(tx){old=tx;return tx.readJournal().then(function(v){check(v);return 'done';});}).then(function(v){assert.strictEqual(v,'done');return reject(old.readJournal());});});
test('lease spans transactions and releases only after close',function(){var a=adapter(),b=adapter(),entered=false;return a.withControllerTransaction(function(tx){return tx.readJournal();}).then(check).then(function(){return reject(b.withControllerTransaction(function(){entered=true;throw Error('contender entered');}));}).then(function(){assert.strictEqual(entered,false);return a.withControllerTransaction(function(tx){return tx.readJournal();});}).then(check).then(function(){return a.close();}).then(function(){var c=adapter();return c.withControllerTransaction(function(tx){return tx.readJournal();});}).then(check);});
test('overlapping transactions do not invoke second callback',function(){var a=adapter(),entered=false;return a.withControllerTransaction(function(tx){return reject(a.withControllerTransaction(function(){entered=true;throw Error('nested callback');})).then(function(){assert.strictEqual(entered,false);return tx.readJournal();});}).then(check);});
test('one outstanding operation without a hidden queue',function(){var a=adapter();return a.withControllerTransaction(function(tx){var first=tx.readJournal();return reject(tx.readJournal()).then(function(){return first;});}).then(check);});
test('ordinary native read failure permits same-scope recovery',function(){var a=adapter();return a.withControllerTransaction(function(tx){fs.unlinkSync(journal+'/entry.0000.json');return reject(tx.readJournal()).then(function(e){assert.strictEqual(e.code,'STOP_IO_NATIVE');fs.writeFileSync(journal+'/entry.0000.json',raw,{mode:384});return tx.readJournal();});}).then(check);});
test('callback error ends transaction before reuse',function(){var a=adapter();return reject(a.withControllerTransaction(function(tx){return tx.readJournal().then(function(){throw Error('callback failure');});})).then(function(){return a.withControllerTransaction(function(tx){return tx.readJournal();});}).then(check);});
test('early callback completion drains then rejects',function(){var a=adapter(),pending,old;return reject(a.withControllerTransaction(function(tx){old=tx;pending=tx.readJournal();return 'unsafe';})).then(function(e){assert.strictEqual(e.code,'STOP_IO_EARLY_RETURN');return pending;}).then(check).then(function(){return reject(old.readJournal());}).then(function(){return a.withControllerTransaction(function(tx){return tx.readJournal();});}).then(check);});
test('maximum bounded read preserves all raw bytes',function(){var spaces=new Array(16385).join(' ');for(var i=0;i<64;i++)fs.writeFileSync(journal+'/entry.'+('0000'+i).slice(-4)+'.json',spaces,{mode:384});var a=adapter();return a.withControllerTransaction(function(tx){return tx.readJournal();}).then(function(v){assert.strictEqual(v.records.length,64);v.records.forEach(function(row,index){assert.strictEqual(row.name,'entry.'+('0000'+index).slice(-4)+'.json');assert.strictEqual(row.raw,spaces);});});});
test('unknown filename is not an empty snapshot',function(){var a=adapter();fs.writeFileSync(journal+'/foreign','x',{mode:384});return a.withControllerTransaction(function(tx){return reject(tx.readJournal()).then(function(){fs.unlinkSync(journal+'/foreign');return tx.readJournal();});}).then(check);});

var chain=Promise.resolve();tests.forEach(function(item){chain=chain.then(function(){reset();return Promise.resolve().then(item[1]).then(function(){count++;return closeAll();},function(e){return closeAll().then(function(){throw Error(item[0]+': '+e.stack);});});});});
chain.then(function(){console.log('PASS '+count+' actual child cases on '+process.version);},function(e){console.error(e.stack);process.exitCode=1;});
